def gen(rng):
    def fmt(a, x=None, y=None):
        if x is None:
            x = min(a)
        if y is None:
            y = max(a)
        return f'{len(a)} {x} {y}\n' + ' '.join(map(str, a))
    tests = [fmt([7]), fmt([3, 7, 9, 2], 1, 10), fmt([1, 2, 1, 2, 1], 1, 5), fmt([5, 5, 5]), fmt([4, 4], 1, 9), fmt([1, 2], 1, 2),
             fmt([1, 2, 3, 4, 5, 6, 7, 8]), fmt([9, 9, 9, 1])]
    for n in (3, 5, 8, 12, 20, 30):
        for hi in (2, 3, 6, 50):
            a = [rng.randint(1, hi) for _ in range(n)]
            tests.append(fmt(a, 1, hi))
    N = 200000
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)], 1, 10**9))
    tests.append(fmt([rng.randint(1, 2) for _ in range(N)], 1, 10**9))
    tests.append(fmt([10**9] * N, 1, 10**9))
    perm = list(range(10**9 - N + 1, 10**9 + 1))
    rng.shuffle(perm)
    tests.append(fmt(perm, 1, 10**9))
    tests.append(fmt([rng.randint(1, 1000) for _ in range(N)], 1, 1000))
    return tests

